/**
 * RNA TESTS: the cancer tests that read RNA rather than DNA, in tumour tissue, in urine and in blood, and the
 * proposal to stack tumour RNA on tumour DNA in a residual disease blood test (4 November 2026).
 *
 * Inventory first. Already in the corpus and only supplemented here: Oncotype DX (breast), MammaPrint, Prosigna,
 * EndoPredict, Breast Cancer Index, Decipher Prostate, Prolaris, the Oncotype DX Genomic Prostate Score, Afirma,
 * Cxbladder, ColoSense, the Oncomine Dx tests, TruSight Oncology Comprehensive, Caris MI Profile and MI Cancer Seek,
 * thromboSeq and GASTROClear. New here: the RNA tests that had no record.
 *
 * Sources. Every PubMed id was resolved through the Europe PMC REST API on 4 November 2026 and its abstract read
 * before a figure was taken; a figure from an open full text says so. Maker statements were read from the raw page
 * with curl and are labelled as the maker's. FDA numbers were read on accessdata.fda.gov. Medicare documents were
 * read through the CMS Medicare Coverage Database API (the same documents as the cms.gov pages). NCCN pages refuse
 * scripts and were not used.
 *
 * Left out on purpose: ColoPrint (Agendia's page now redirects to its home page and no statement of withdrawal was
 * found), Percepta (the bronchial classifier is no longer listed by Veracyte and the nasal swab is labelled "in
 * pipeline"), MyPRS (no maker page resolves), Mursla Bio's EvoLiver (its page does not say it reads RNA), Tempus
 * xR's maker page (refused the request; the record rests on the FDA file and a paper), and the FDA Breakthrough
 * designation of ExoDx Prostate (stated only by the maker).
 *
 * The cancer links follow a coverage decision, a label or the validation paper's own population, so each test is
 * linked to the cancers its evidence is about and no wider.
 */
const asOf = "2026-11-04";
const doiUrl = (d: string) => `https://doi.org/${d}`;
const pubmed = (p: string) => `https://pubmed.ncbi.nlm.nih.gov/${p}/`;
const ref = (label: string, doi: string, pmid: string) => [{ label, url: doiUrl(doi) }, { label: "PubMed", url: pubmed(pmid) }];
const lcd = (id: string, title: string) => ({ label: `CMS LCD L${id}: ${title}`, url: `https://www.cms.gov/medicare-coverage-database/view/lcd.aspx?lcdid=${id}` });
const article = (id: string, title: string) => ({ label: `CMS article A${id}: ${title}`, url: `https://www.cms.gov/medicare-coverage-database/view/article.aspx?articleid=${id}` });
const K510 = (n: string) => ({ label: `FDA 510(k) ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=${n}` });
const PMA = (n: string) => ({ label: `FDA PMA ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpma/pma.cfm?id=${n}` });

const test = (x: Omit<DrugInput, "kind" | "asOf">): DrugInput => ({ kind: "drug", asOf, ...x, tags: ["test", "rna", ...(x.tags ?? [])] });
const p = (x: Omit<PaperInput, "kind" | "asOf">): PaperInput => ({ kind: "paper", asOf, ...x });

